ecommerce_catalog.dsl:
// =============================================================================
// E-Commerce Catalog & Multi-Variant Extraction Pipeline
// =============================================================================

let origin = "https://audiohub.example"

catalog = Scraper()
  | $("div.product-item", "items") {
      @"data-id" -> "product_id"
      | @"data-available" | to_bool(key="available")
      | find("h3.name") | clean -> "name"
      | find(".price", Attribute, "data-usd") | to_float(key="price_usd")
      | find_all(".badge") | clean -> "badges"
      | find_all(".variants .color", Attribute, "data-color") -> "available_colors"
      | find_all(".variants .color", Attribute, "data-sku") -> "variant_skus"
      | find("a.p-link", Attribute, "href") | url_join(origin) -> "url"
    }
  | $("nav.pagination") {
      find("span.current") | clean -> "page_status"
      | find("a.next-page", Attribute, "href") | url_join(origin) -> "next_page_url"
    }

ex_01_dsl_syntax.dsl:
// @playground id=ex_01_dsl_syntax label="01: DSL Syntax & Flow" scraper=syntax_and_aliases
# Hash single-line comment
// C++ style single-line comment
/* Multi-line
   block comment */

let base_url = "https://shop.example"
let title_sel = "h1.brand"
let escaped_var = "literal \${base_url}"

// Reusable pipe fragment + use()
pipe kv_pair = {
  find("dt", Text) -> "@key"
  | find("dd", Text) -> "@value"
}

// Base scraper for include()
base_meta = Scraper()
  | $(title_sel, "meta") {
      text | squish -> "brand"
    }

// Demonstrates declarations (=, :, :=, implicit), separators (. | |>),
// shorthands ($ @ ?? [0] [-1] -> >> as), all 17 aliases, and multiline strings.
syntax_and_aliases: ScraperPy()
  .include(base_meta)
  |> $("header.site-header", "header") {
       // Shorthands: @ident, @"attr", @("attr"), @[fallback list]
       // Note: bare @ident allows [A-Za-z_][A-Za-z0-9_]*; hyphenated attrs use @"data-env"
       @class -> "header_class"
       | @"data-env" >> "env"
       | @("data-env") as "env_alias"
       | find("span.subtitle", Attribute, ["data-missing", "data-alt"]) -> "sub_alt"
       | find("span.missing", Text) ?? "Default Fallback" -> "fallback_val"
       | find("span.subtitle", Text) | strip | clean | normalize_whitespace -> "subtitle_clean"
       | find("span.subtitle", Text) | sub("Fast", "Ultra-Fast") | extract("(Ultra-Fast)", 1) -> "extracted"
       | find("span.subtitle", Text) | grep("Fast") -> "grepped"
       | find("h1.brand", Text) | inner_html -> "noop_text_check"
     }
  . $("article.card[data-id='101']", "card") {
       @"data-id" | as("id", "int")
       | find("h2.name", Text) | clean -> "name"
       | find(".price", Text) | to_number(key="price")
       | find("a.cta", Attribute, "href") | url_join(base_url) -> "cta_url"
       | find_all(".tags span", Text) | strip | dedup | limit(2) -> "top_tags"
       | find_all(".tags span", Text) | strip | [0] -> "first_tag"
       | find_all(".tags span", Text) | strip | [-1] -> "last_tag"
       | find("div.raw-json", Text) | json("parsed_json")
       | find("script", Text) | extract_js_block("window.__CFG__ =") | parse_js("cfg")
       | find_all("script", Text) | extract_js_blocks(["window.__CFG__ =", "window.__META__ ="], {"window.__CFG__ =": "cfg_alias", "window.__META__ =": "meta_alias"})
       | fields({ title: { sel: "h2.name", squish: true }, price_raw: { sel: ".price", trim: true } })
       | find("h2.name", Text) | clean | branch {
           upper -> "name_upper"
         } | lower -> "name_lower"
       .(.find(".badge", Text) | upper -> "grouped_badge")
     }
  | $("dl.specs", "specs_list") {
      // Nested relative $ block + @key/@value
      each("dt", "") {
        text -> "dt_only"
      }
    }
  | $("dl.specs", "specs_kv") {
      use(kv_pair)
    }
  | $("div.nested-groups div.group", "groups") {
      @"data-group" -> "group"
      | $("li", "items") {
          @"data-code" -> "code"
          | text -> "label"
        }
    }
  | finalize {
      jmespath("{
        brand: meta.brand,
        env: header.env,
        card_id: card.id,
        card_name_upper: card.name_upper,
        card_name_lower: card.name_lower,
        escaped: `\"${escaped_var}\"`
      }")
    }

// Control flow, guards, save/restore, tee, when_exists/unless_exists/when_match
control_flow := Scraper()
  | $("article.card", "filtered_cards") {
      skip_if_exists("span.skip-marker")
      | find("h2.name", Text) | skip_if_empty()
      | save("orig_name")
      | tee {
          upper -> "upper_name"
        }
      | restore("orig_name")
      | lower -> "lower_name"
      | when_exists("span.badge") {
          find("span.badge", Text) -> "badge"
        }
      | unless_exists("span.out-of-stock") {
          find(".price", Text) | when_match("\\$19", flags="i") {
            prepend("USD ") -> "matched_price"
          }
        }
    }
  | $("div.abort-zone", "abort_demo") {
      find("span.normal", Text) -> "normal"
      | abort_if_exists("span.maintenance", key="aborted_reason", reason="maintenance_mode")
    }
  | $("header.site-header", "never_reached_after_abort") {
      find("h1.brand", Text) -> "brand"
    }

// Implicit root scraper + @key/@value collapsing
implicit_root = .select("dl.specs") {
  find("dt", Text) -> "@key"
  | find("dd", Text) -> "@value"
}

ex_02_dom_selection.dsl:
// @playground id=ex_02_dom_selection label="02: DOM, XPath & Tables" scraper=dom_and_values
dom_and_values = Scraper()
  | $("section#dom-box", "box") {
      tag_name() -> "tag"
      | classes() -> "classes"
      | attrs(data_only=true)
      | find("p.intro", Value.Text, squish=true) -> "full_text"
      | find("p.intro", Value.OwnText, squish=true) -> "own_text"
      | find("a.doc-link", Value.Attribute, ["data-missing", "href"]) -> "href"
      | find("a.doc-link", Value.ElementExists) -> "link_exists"
      | find("a.doc-link", Value.AttributeExists, "data-alt") -> "has_data_alt"
      | find("div.rich", Value.Text) -> "rich_text"
    }
  | $("ul.xml-items", "box") {
      find_all("li", Value.Text) -> "all_li"
    }
  | $("span.label", "box") {
      find("span.next-label", Value.Adjacent) -> "adjacent_text"
    }
  | $("div.rich", "html_inspect") {
      html(outer=false) -> "inner"
      | html(outer=true) -> "outer_flag"
      | outer_html() -> "outer"
    }
  | $("p.intro", "text_modes") {
      text(own_text=false) | squish -> "text_full"
      | text(own_text=true) | squish -> "text_own"
    }
  | $("a.doc-link", "attr_list") {
      attr(["data-missing", "data-alt", "href"]) -> "first_found_attr"
    }
  | $("section#dom-box", "fields_demo") {
      extract_fields({
        heading: { selector: "p.intro", type: "own_text", squish: true },
        doc_href: { sel: "a.doc-link", type: "attr", attr: "href", trim: true },
        missing_opt: { sel: ".missing", default: "N/A" },
        box_id: { sel: "a.doc-link", type: "exists", cast: "bool" }
      }, allow_empty=false)
    }

xpath_tables_meta = Scraper()
  | extract_meta("meta", include_json_ld=true, index_json_ld=true)
  | $("table.pricing") {
      table(key="pricing_rows", header=true, normalize_headers=true, trim_cells=true)
    }
  | $("table.no-header") {
      table(key="raw_rows", header=false, trim_cells=true)
    }
  | $("ul.xml-items", "xpath_demo") {
      xpath(".//li/text()") -> "xp1_texts"
      | xpath(".//li", attr="data-idx") -> "xp1_attrs"
      | xpath3("string-join(.//li/text(), ', ')") -> "xp3_joined"
      | xpath3(".//li", attr="data-idx") -> "xp3_attrs"
    }

ex_03_text_encoding.dsl:
// @playground id=ex_03_text_encoding label="03: Text, Encoding & Unicode" scraper=text_and_encoding
text_and_encoding = Scraper()
  | $("h1.heading", "case_and_ws") {
      text | trim() -> "trimmed"
      | text | squish() -> "squished"
      | text | normalize_whitespace() -> "norm_ws"
      | text | squish() | lower() -> "lowered"
      | text | squish() | upper() -> "uppered"
      | text | squish() | substring(0, 5) -> "sub_prefix"
      | text | squish() | substring(-6) -> "sub_suffix"
      | text | squish() | unicode_normalize("NFC") -> "nfc"
      | text | squish() | unicode_normalize("NFD") -> "nfd"
      | text | squish() | unicode_normalize("NFKC") -> "nfkc"
      | text | squish() | unicode_normalize("NFKD") | strip_accents() -> "ascii_folded"
      | text | squish() | strip_accents() | slugify("_", 20) -> "slug"
      | text | squish() | hash("fnv1a64") -> "fnv1a64"
      | text | squish() | hash("sha256") -> "sha256"
    }
  | $("div.escaped", "escapes") {
      text | unescape(url_decode=true) -> "full_unescape"
      | text | unescape(url_decode=false) -> "no_url_decode"
    }
  | $("div.entities", "html_ent") {
      text | unescape_html() -> "decoded"
    }
  | $("div.code-text", "comments_and_replace") {
      text | strip_comments(multiline=true, single_line=true) | squish -> "no_comments"
      | text | strip_comments(multiline=true, single_line=false) | squish -> "keep_single_line"
      | text | strip_comments() | squish | replace("hello", "hi", first_only=true) -> "replaced_one"
      | text | strip_comments() | squish | replace({"hello": "greetings", "world": "earth"}) -> "replaced_map"
    }
  | $("div.html-snippet", "tags") {
      html() | strip_tags() | squish -> "stripped_tags"
    }
  | $("div.csv-line", "lists") {
      text | split(",", keep_empty_parts=true) | drop_empty(also_trim=true) | prepend("[") | append("]") | join(" | ") -> "cleaned_joined"
      | text | split(",", keep_empty_parts=false) -> "split_nonempty"
    }
  | $("div.b64-std", "base64") {
      text | trim | base64_decode(urlsafe=false) -> "decoded_std"
      | text | trim | base64_decode() | base64_encode(urlsafe=false) -> "roundtrip_std"
      | text | trim | base64_decode() | base64_encode(urlsafe=true) -> "encoded_urlsafe"
    }
  | $("div.b64-url", "base64") {
      text | trim | base64_decode(urlsafe=true) -> "decoded_urlsafe"
    }
  | $("ul.statuses", "mapping") {
      find_all("li", Text) | map_values({"IN_STOCK": "available", "BACKORDER": "delayed"}, default_val="other") -> "mapped"
    }

ex_04_urls_web.dsl:
// @playground id=ex_04_urls_web label="04: URLs, Srcset & CSS URL" scraper=urls_and_web
let base = "https://shop.example.com:443/catalog/index.html"

urls_and_web = Scraper()
  | $("a.rel", "url_parts") {
      @href | resolve_url(base) -> "resolved"
      | @href | resolve_url(base) | url_part("scheme") -> "scheme"
      | @href | resolve_url(base) | url_part("host") -> "host"
      | @href | resolve_url(base) | url_part("port") -> "port"
      | @href | resolve_url(base) | url_part("path") -> "path"
      | @href | resolve_url(base) | url_part("query") -> "query"
      | @href | resolve_url(base) | url_part("fragment") -> "fragment"
      | @href | resolve_url(base) | query_param("q", "none") -> "q_decoded"
      | @href | resolve_url(base) | query_param("missing", "fallback") -> "q_missing"
      | @href | resolve_url(base) | strip_query(keep_params=["ref", "q"]) -> "kept_query"
      | @href | resolve_url(base) | strip_query(drop_params=["utm_*"]) -> "dropped_utm"
