ex_05_regex_fuzzy.dsl:
// @playground id=ex_05_regex_fuzzy label="05: Regex, Aho-Corasick & Fuzzy" scraper=regex_ac_fuzzy
regex_ac_fuzzy = Scraper()
  | $("section.regex-box", "regex") {
      find("h1.title", Text) | regex_replace("\\s+", " ") -> "norm"
      | find("h1.title", Text) | regex_extract("#([A-Z]+)-([0-9]+)", 2) -> "order_num"
      | find("h1.title", Text) | regex_groups("(?P<code>[a-z]+)-(?P<num>[0-9]+)", flags="i", prefix="ord_")
      | find("p.prices", Text) | regex_find_all("\\$([0-9]+\\.[0-9]{2})", 1) -> "all_prices"
      | find("pre.multiline", Text, squish=false) | regex_replace("alpha.*BETA", "MATCHED", flags="is") -> "dotall_replaced"
      | find("pre.multiline", Text, squish=false) | split("\n") | regex_filter("^line", negate=false, flags="im") -> "multiline_lines"
      | find_all("ul.codes li", Text) | regex_filter("REFURB", negate=true) -> "non_refurb"
    }
  | $("section.regex-box", "ac") {
      find_all("ul.codes li", Text) | filter(["PRO", "100"]) -> "filtered_codes"
      | find("div.notes", Text) | extract_many(["C++20", "RE2", "Aho-Corasick", "Python"], unique=true) -> "tech_unique"
      | find("div.notes", Text) | extract_many(["C++20", "RE2"], unique=false) -> "tech_all"
    }
  | $("ul.fuzzy-list", "fuzzy") {
      find_all("li", Text) | fuzzy_filter("Mechanical Keyboard", threshold=0.75, algo="jaro_winkler", case_sensitive=false, sort_by_score=true) -> "jw_matches"
      | find_all("li", Text) | fuzzy_filter("Mechanical Keyboard", threshold=0.70, algo="levenshtein", case_sensitive=false, sort_by_score=true) -> "lev_matches"
      | find_all("li", Text) | similarity("Mechanical Keyboard", algo="jaro_winkler", case_sensitive=false, key="jw_scores")
      | find_all("li", Text) | similarity("Mechanical Keyboard", algo="levenshtein", case_sensitive=false) -> "lev_scores_str"
    }

ex_07_js_json_csv.dsl:
// @playground id=ex_07_js_json_csv label="07: JS Digger, JSON, CSV & Queries" scraper=js_json_csv
js_json_csv = Scraper()
  | $("script#hydration", "js") {
      text | js_block("window.__DATA__ =") | parse_js("data", simplify=true)
      | text | js_blocks({"window.__DATA__ =": "d", "window.__EXTRA__ =": "extra"})
    }
  | $("div.json-commented", "json_ops") {
      text | json_parse("cfg", allow_comments=true, allow_trailing_comma=true, allow_inf_and_nan=false, lossless_number=false, max_nesting_depth=64, strict=true)
      | json_dump(pretty=true, indent=2, source_key="cfg") -> "cfg_pretty"
    }
  | $("div.json-lenient", "json_ops") {
      text | json_parse("lenient_obj", lenient=true)
    }
  | $("pre.csv-block", "csv_ops") {
      text | trim | csv_parse("rows", assume_header=true, delimiter=",", trim=true, strict=true)
      | csv_dump(assume_header=true, delimiter=";", trim=true, source_key="rows") -> "csv_semicolon"
    }
  | finalize {
      json_schema({
        "type": "object",
        "required": ["js", "json_ops", "csv_ops"]
      }, strict=false, error_key="_schema_errors")
    }

query_projections = Scraper()
  | $("script#hydration") {
      text | js_block("window.__DATA__ =") | parse_js("data")
    }
  | $("pre.csv-block") {
      text | trim | csv_parse("rows")
    }
  | finalize {
      jsonpath("$.rows[?(@.score == 95)].name")
    }

jmespath_projection = Scraper()
  | $("script#hydration") {
      text | js_block("window.__DATA__ =") | parse_js("data")
    }
  | finalize {
      jmespath("{sku: data.sku, price: data.price, nested: data.payload.nested}")
    }

marketplace.dsl:
// =============================================================================
// xsel2 - Comprehensive Marketplace Example
// =============================================================================
// Demonstrates:
//   - DSL variables, pipe sugar (|, ->, ??, @attr, $(...) { ... })
//   - DOM, text, regex, and slicing steps
//   - Lenient JS/JSON digger (js_block, js_blocks, parse_js with simplify=true)
//   - Relaxed JSON-LD (json_parse) and CSV (csv_parse)
//   - JSONPath (jsonpath), JSON Schema (json_schema), and JMESPath normalization.
// =============================================================================

let card_sel = ".product-card"
let json_ld_sel = "script[type='application/ld+json']"

// 1. Full extraction + lenient digger + JSON transformations & validation
catalog_full = Scraper()
  | $("head title", "storefront") {
      text | unescape | clean -> "title"
    }
  | $("link[rel='canonical']", "storefront") {
      @href -> "canonical_url"
    }
  | $(".promo-banner", "storefront") {
      text | unescape | clean | sub("Spring\\s+Sale:", "Featured:") -> "promo"
    }
  | $("nav.breadcrumbs", "storefront") {
      find_all("a", Value.Text) | unescape | clean | dedup | slice(1, 2) -> "breadcrumbs"
    }
  | $(card_sel, "products") {
      @"data-sku" -> "sku"
      | @"data-category" -> "category"
      | @"data-in-stock" -> "in_stock"
      | find("h2.name", Value.Text) | clean -> "name"
      | find("span.price", Value.Text) | extract("([0-9]+\\.[0-9]+)", 1) ?? "0.00" -> "price"
      | find_all("span.badge", Value.Text) | clean | dedup -> "badges"
      | find_all("ul.specs li", Value.Text) | clean -> "specs"
      | find("div.seller", Value.OwnText) | clean -> "seller"
      | find("div.seller span.rating", Value.Text) | clean -> "rating"
    }
  | $(json_ld_sel, "json_ld") {
      text | json_parse(allow_comments=true, allow_trailing_comma=true, strict=false)
    }
  | $("script#shipping-rates") {
      text | trim | csv_parse("shipping_rates", assume_header=true, delimiter=",", trim=true, strict=false)
    }
  | $("script") {
      text | js_block("window.__CATALOG_STATE__ =") | parse_js("hydration", true)
      | text | js_blocks(["window.__PROMO_CONFIG__"])
    }
  // Top-level JSON transformations & validation
  | omit_keys(["apiSecret", "wholesaleCost"])
  | deduplicate()
  | sort_array(true)
  | json_schema({
      "type": "object",
      "required": ["storefront", "products", "hydration", "shipping_rates"],
      "properties": {
        "products": {"type": "array", "minItems": 1}
      }
    }, strict=false, error_key="_schema_errors")


// 2. Normalized summary via JMESPath post-processing
catalog_summary = Scraper()
  | $("head title", "storefront") { text | unescape | clean -> "title" }
  | $(card_sel, "products") {
      @"data-sku" -> "sku"
      | @"data-in-stock" -> "in_stock"
      | find("h2.name", Value.Text) | clean -> "name"
      | find("span.price", Value.Text) | extract("([0-9]+\\.[0-9]+)", 1) ?? "0.00" -> "price"
      | find("div.seller", Value.OwnText) | clean -> "seller"
    }
  | $(json_ld_sel, "json_ld") {
      text | json_parse(allow_comments=true, allow_trailing_comma=true, strict=false)
    }
  | $("script#shipping-rates") {
      text | trim | csv_parse("shipping_rates", assume_header=true, delimiter=",", trim=true, strict=false)
    }
  | $("script") {
      text | js_block("window.__CATALOG_STATE__ =") | parse_js("hydration", true)
    }
  | jmespath("{
      store: storefront.title,
      total_items: json_ld.numberOfItems,
      warehouse: hydration.fulfillment.warehouse,
      api_base: hydration.apiBase,
      in_stock_products: products[?in_stock == 'true'].{
        sku: sku,
        name: name,
        price: price,
        seller: seller
      },
      shipping_carriers: shipping_rates[*].carrier
    }
  ")


// 3. JSONPath query scraper
product_skus = Scraper()
  | $(card_sel, "products") { @"data-sku" -> "sku" }
  | jsonpath("$.products[*].sku")

metadata.dsl:
// =============================================================================
// xsel2 - Exhaustive DSL for HTML Metadata, JSON, and Schema Extraction
// =============================================================================
// Extracts standard HTML metadata, http-equiv, Open Graph (core, article, book,
// profile, music, video, product), Twitter/X Cards (incl. Slack/Discord),
// Facebook, Instagram & App Links, Dublin Core, Google Scholar, Parse.ly,
// Sailthru, Apple/iOS, Microsoft/Windows, Pinterest, Domain Verification,
// <link> relations (SEO, Feeds, IndieWeb, Fediverse, Monetization), JSON-LD,
// modern framework JSONs/states (Next.js, Nuxt, Remix, Angular, SvelteKit,
// Shopify, importmap, speculationrules), Microdata, RDFa, and generic fallback
// arrays (all_meta, all_links).
// =============================================================================

metadata = Scraper()
  // ---------------------------------------------------------------------------
  // 1. Basic HTML
  // ---------------------------------------------------------------------------
  | $("html", "basic") {
      @lang | clean -> "lang"
      | @dir | clean -> "dir"
    }
  | $("head title", "basic")                 { text | clean -> "title" }
  | $("meta[charset]", "basic")              { @charset | lower | clean -> "charset" }
  | $("meta[name='description']", "basic")   { @content | clean -> "description" }
  | $("meta[name='keywords']", "basic")      { @content | clean -> "keywords" }
  | $("meta[name='news_keywords']", "basic") { @content | clean -> "news_keywords" }
  | $("meta[name='author']", "basic")        { @content | clean -> "author" }
  | $("meta[name='creator']", "basic")       { @content | clean -> "creator" }
  | $("meta[name='publisher']", "basic")     { @content | clean -> "publisher" }
  | $("meta[name='generator']", "basic")     { @content | clean -> "generator" }
  | $("meta[name='application-name']", "basic") { @content | clean -> "application_name" }
  | $("meta[name='robots']", "basic")        { @content | clean -> "robots" }
  | $("meta[name='googlebot']", "basic")     { @content | clean -> "googlebot" }
  | $("meta[name='bingbot']", "basic")       { @content | clean -> "bingbot" }
  | $("meta[name='viewport']", "basic")      { @content | clean -> "viewport" }
  | $("meta[name='theme-color']", "basic")   { @content | clean -> "theme_color" }
  | $("meta[name='color-scheme']", "basic")  { @content | clean -> "color_scheme" }
  | $("meta[name='referrer']", "basic")      { @content | clean -> "referrer" }
  | $("meta[name='rating']", "basic")        { @content | clean -> "rating" }
  | $("meta[name='format-detection']", "basic") { @content | clean -> "format_detection" }
  | $("meta[name='copyright']", "basic")     { @content | clean -> "copyright" }
  | $("meta[name='language']", "basic")      { @content | clean -> "language" }
  | $("meta[name='revisit-after']", "basic") { @content | clean -> "revisit_after" }
  | $("meta[name='distribution']", "basic")  { @content | clean -> "distribution" }
  | $("meta[name='syndication-source']", "basic") { @content | clean -> "syndication_source" }
  | $("meta[name='original-source']", "basic")    { @content | clean -> "original_source" }
  | $("meta[name='standout']", "basic")      { @content | clean -> "standout" }
  | $("meta[name='geo.region']", "basic")    { @content | clean -> "geo_region" }
  | $("meta[name='geo.placename']", "basic") { @content | clean -> "geo_placename" }
  | $("meta[name='geo.position']", "basic")  { @content | clean -> "geo_position" }
  | $("meta[name='ICBM']", "basic")          { @content | clean -> "icbm" }
  | $("meta[name='fediverse:creator'], meta[property='fediverse:creator']", "basic") { @content | clean -> "fediverse_creator" }
  | $("meta[name='telegram:channel'], meta[property='telegram:channel']", "basic")   { @content | clean -> "telegram_channel" }

  // ---------------------------------------------------------------------------
  // 2. http-equiv Directives
  // ---------------------------------------------------------------------------
  | $("meta[http-equiv='content-type'], meta[http-equiv='Content-Type']", "http_equiv")                       { @content | clean -> "content_type" }
  | $("meta[http-equiv='content-language'], meta[http-equiv='Content-Language']", "http_equiv")               { @content | clean -> "content_language" }
  | $("meta[http-equiv='refresh'], meta[http-equiv='Refresh']", "http_equiv")                                 { @content | clean -> "refresh" }
  | $("meta[http-equiv='Content-Security-Policy'], meta[http-equiv='content-security-policy']", "http_equiv") { @content | clean -> "content_security_policy" }
  | $("meta[http-equiv='X-UA-Compatible'], meta[http-equiv='x-ua-compatible']", "http_equiv")                 { @content | clean -> "x_ua_compatible" }
  | $("meta[http-equiv='cache-control'], meta[http-equiv='Cache-Control']", "http_equiv")                     { @content | clean -> "cache_control" }

  // ---------------------------------------------------------------------------
  // 3. Open Graph Protocol (Core, Media, and Namespaces)
  // ---------------------------------------------------------------------------
  | $("meta[property='og:title'], meta[name='og:title']", "open_graph")               { @content | clean -> "title" }
  | $("meta[property='og:type'], meta[name='og:type']", "open_graph")                 { @content | clean -> "type" }
  | $("meta[property='og:url'], meta[name='og:url']", "open_graph")                   { @content | clean -> "url" }
  | $("meta[property='og:description'], meta[name='og:description']", "open_graph")   { @content | clean -> "description" }
